82	/****************************************************************************
83	 * Name: gpio_handler
84	 *
85	 * Description:
86	 *   GPIO interrupt callback function.
87	 *
88	 ****************************************************************************/
89	
90	static int gpio_handler(FAR struct gpio_dev_s *dev, uint8_t pin)
91	{
92	#if CONFIG_DEV_GPIO_NSIGNALS > 0
93	  int i;
94	#endif
95	
96	  DEBUGASSERT(dev != NULL);
97	
98	  dev->int_count++;
99	
100	#if CONFIG_DEV_GPIO_NPOLLWAITERS > 0
101	  poll_notify(dev->fds, CONFIG_DEV_GPIO_NPOLLWAITERS, POLLIN);
102	#endif
103	
104	#if CONFIG_DEV_GPIO_NSIGNALS > 0
105	  for (i = 0; i < CONFIG_DEV_GPIO_NSIGNALS; i++)
106	    {
107	      FAR struct gpio_signal_s *signal = &dev->gp_signals[i];
108	
109	      if (signal->gp_pid == 0)
110	        {
111	          break;
112	        }
113	
114	#  ifdef CONFIG_SIG_EVTHREAD
115	      nxsig_notification(signal->gp_pid, &signal->gp_event,
116	                         SI_QUEUE, &signal->gp_work);
117	#  else
118	      nxsig_notification(signal->gp_pid, &signal->gp_event, SI_QUEUE, NULL);
119	#  endif
120	    }
121	#endif
122	
123	  return OK;
124	}
