181	
182	static int bk7258_gpio_result(bk_err_t error)
183	{
184	  if (error == BK_OK)
185	    {
186	      return OK;
187	    }
188	
189	  if (error == BK_ERR_GPIO_INTERNAL_USED)
190	    {
191	      return -EBUSY;
192	    }
193	
194	  return -EIO;
195	}
196	
197	static uint32_t bk7258_gpio_enable_route(uint32_t *saved)
198	{
199	  volatile uint32_t *reg =
200	    (volatile uint32_t *)(uintptr_t)BK7258_GPIO_ROUTE_REG;
201	  irqstate_t flags;
202	  uint32_t value;
203	
204	  flags = enter_critical_section();
205	  *saved = *reg;
206	  *reg = *saved | BK7258_GPIO_ROUTE_MASK;
207	  value = *reg;
208	  leave_critical_section(flags);
209	  return value;
210	}
211	
212	static uint32_t bk7258_gpio_restore_route(uint32_t saved)
213	{
214	  volatile uint32_t *reg =
215	    (volatile uint32_t *)(uintptr_t)BK7258_GPIO_ROUTE_REG;
216	  irqstate_t flags;
217	  uint32_t value;
218	
219	  flags = enter_critical_section();
220	  value = *reg;
221	  value &= ~BK7258_GPIO_ROUTE_MASK;
222	  value |= saved & BK7258_GPIO_ROUTE_MASK;
223	  *reg = value;
224	  value = *reg;
225	  leave_critical_section(flags);
226	  return value;
227	}
228	
229	static int bk7258_gpio_close_route(
230	  FAR struct bk7258_gpio_interrupt_s *key)
231	{
232	  uint32_t value;
233	  bk_err_t error;
234	  int result = OK;
235	
236	  if (key->route_gate_touched)
237	    {
238	      value = bk7258_gpio_restore_route(key->saved_route);
239	      if ((value & BK7258_GPIO_ROUTE_MASK) !=
240	          (key->saved_route & BK7258_GPIO_ROUTE_MASK))
241	        {
242	          result = -EIO;
243	        }
244	      else
245	        {
246	          key->route_gate_touched = false;
247	        }
248	    }
249	
250	  if (key->nonsecure_route_touched)
251	    {
252	      if (key->saved_nonsecure_handler != NULL)
253	        {
254	          error = bk_int_isr_register(BK7258_GPIO_NONSECURE_SOURCE,
255	                                      key->saved_nonsecure_handler, NULL);
256	        }
257	      else
258	        {
259	          error = bk_int_isr_unregister(BK7258_GPIO_NONSECURE_SOURCE);
260	        }
261	
262	      if (error != BK_OK)
263	        {
264	          if (result == OK)
265	            {
266	              result = -EIO;
267	            }
268	        }
269	      else
270	        {
271	          key->nonsecure_route_touched = false;
272	          key->saved_nonsecure_handler = NULL;
273	        }
274	    }
275	
276	  return result;
277	}
278	
279	static int bk7258_gpio_open_route(
280	  FAR struct bk7258_gpio_interrupt_s *key)
281	{
282	  int_group_isr_t secure_handler = NULL;
283	  int_group_isr_t nonsecure_handler = NULL;
284	  uint32_t value;
285	  bk_err_t error;
286	
287	  error = bk7258_sdk_irq_snapshot_handler(BK7258_GPIO_SECURE_SOURCE,
288	                                           &secure_handler);
289	  if (error != BK_OK || secure_handler == NULL)
290	    {
291	      return -EIO;
292	    }
293	
294	  error = bk7258_sdk_irq_snapshot_handler(BK7258_GPIO_NONSECURE_SOURCE,
295	                                           &nonsecure_handler);
296	  if (error != BK_OK)
297	    {
298	      return -EIO;
299	    }
300	
301	  if (nonsecure_handler != secure_handler)
302	    {
303	      if (nonsecure_handler != NULL)
304	        {
305	          return -EBUSY;
306	        }
307	
308	      error = bk_int_isr_register(BK7258_GPIO_NONSECURE_SOURCE,
309	                                  secure_handler, NULL);
310	      if (error != BK_OK)
311	        {
312	          return -EIO;
313	        }
314	
315	      key->saved_nonsecure_handler = nonsecure_handler;
316	      key->nonsecure_route_touched = true;
317	    }
318	
319	  value = bk7258_gpio_enable_route(&key->saved_route);
320	  key->route_gate_touched = true;
321	  if ((value & BK7258_GPIO_ROUTE_MASK) != BK7258_GPIO_ROUTE_MASK)
322	    {
323	      (void)bk7258_gpio_close_route(key);
324	      return -EIO;
325	    }
326	
327	  return OK;
328	}
