482	static int bk7258_gpio_key_attach(FAR struct gpio_dev_s *dev,
483	                                  pin_interrupt_t callback)
484	{
485	  FAR struct bk7258_gpio_interrupt_s *key =
486	    (FAR struct bk7258_gpio_interrupt_s *)dev;
487	  gpio_isr_t isr;
488	  bk_err_t error;
489	  int result;
490	
491	  if (key == NULL)
492	    {
493	      return -EINVAL;
494	    }
495	
496	  result = nxmutex_lock(&key->lock);
497	  if (result < 0)
498	    {
499	      return result;
500	    }
501	
502	  if (key->enabled)
503	    {
504	      nxmutex_unlock(&key->lock);
505	      return -EBUSY;
506	    }
507	
508	  isr = callback != NULL ? bk7258_gpio_key_isr : NULL;
509	  error = bk_gpio_register_isr(key->pin, isr);
510	  result = bk7258_gpio_result(error);
511	  if (result == OK)
512	    {
513	      key->callback = callback;
514	    }
515	
516	  nxmutex_unlock(&key->lock);
517	  return result;
518	}
