520	static int bk7258_gpio_key_enable(FAR struct gpio_dev_s *dev, bool enable)
521	{
522	  FAR struct bk7258_gpio_interrupt_s *key =
523	    (FAR struct bk7258_gpio_interrupt_s *)dev;
524	  gpio_int_type_t type;
525	  bk_err_t error;
526	  int cleanup_result;
527	  int result;
528	
529	  if (key == NULL)
530	    {
531	      return -EINVAL;
532	    }
533	
534	  result = nxmutex_lock(&key->lock);
535	  if (result < 0)
536	    {
537	      return result;
538	    }
539	
540	  if (enable && key->enabled)
541	    {
542	      nxmutex_unlock(&key->lock);
543	      return OK;
544	    }
545	
546	  if (!enable)
547	    {
548	      result = bk7258_gpio_result(bk_gpio_disable_interrupt(key->pin));
549	      error = bk_gpio_clear_interrupt(key->pin);
550	      if (result == OK)
551	        {
552	          result = bk7258_gpio_result(error);
553	        }
554	
555	      cleanup_result = bk7258_gpio_close_route(key);
556	      if (result == OK)
557	        {
558	          result = cleanup_result;
559	        }
560	
561	      key->enabled = false;
562	      nxmutex_unlock(&key->lock);
563	      return result;
564	    }
565	
566	  if (key->callback == NULL)
567	    {
568	      nxmutex_unlock(&key->lock);
569	      return -EINVAL;
570	    }
571	
572	  result = bk7258_gpio_key_interrupt_type(
573	             (enum gpio_pintype_e)key->gpio.gp_pintype, &type);
574	  if (result < 0)
575	    {
576	      nxmutex_unlock(&key->lock);
577	      return result;
578	    }
579	
580	  result = bk7258_gpio_result(
581	             bk_gpio_set_interrupt_type(key->pin, type));
582	  if (result < 0)
583	    {
584	      nxmutex_unlock(&key->lock);
585	      return result;
586	    }
587	
588	  result = bk7258_gpio_result(bk_gpio_clear_interrupt(key->pin));
589	  if (result < 0)
590	    {
591	      nxmutex_unlock(&key->lock);
592	      return result;
593	    }
594	
595	  result = bk7258_gpio_open_route(key);
596	  if (result < 0)
597	    {
598	      nxmutex_unlock(&key->lock);
599	      return result;
600	    }
601	
602	  result = bk7258_gpio_result(bk_gpio_enable_interrupt(key->pin));
603	  if (result < 0)
604	    {
605	      (void)bk7258_gpio_close_route(key);
606	      nxmutex_unlock(&key->lock);
607	      return result;
608	    }
609	
610	  key->enabled = true;
611	  nxmutex_unlock(&key->lock);
612	  return OK;
613	}
