615	static int bk7258_gpio_key_setpintype(FAR struct gpio_dev_s *dev,
616	                                      enum gpio_pintype_e pintype)
617	{
618	  FAR struct bk7258_gpio_interrupt_s *key =
619	    (FAR struct bk7258_gpio_interrupt_s *)dev;
620	  gpio_int_type_t type;
621	  int result;
622	
623	  if (key == NULL)
624	    {
625	      return -EINVAL;
626	    }
627	
628	  switch (pintype)
629	    {
630	      case GPIO_INPUT_PIN_PULLUP:
631	      case GPIO_INTERRUPT_PIN:
632	      case GPIO_INTERRUPT_RISING_PIN:
633	      case GPIO_INTERRUPT_FALLING_PIN:
634	        break;
635	
636	      default:
637	        return -ENOTSUP;
638	    }
639	
640	  result = nxmutex_lock(&key->lock);
641	  if (result < 0)
642	    {
643	      return result;
644	    }
645	
646	  if (key->enabled || key->callback != NULL)
647	    {
648	      nxmutex_unlock(&key->lock);
649	      return -EBUSY;
650	    }
651	
652	  result = bk7258_gpio_result(
653	             bk_gpio_set_config(key->pin, &g_bk7258_gpio_key_config));
654	  if (result < 0)
655	    {
656	      nxmutex_unlock(&key->lock);
657	      return result;
658	    }
659	
660	  if (pintype >= GPIO_INTERRUPT_PIN)
661	    {
662	      result = bk7258_gpio_key_interrupt_type(pintype, &type);
663	      if (result == OK)
664	        {
665	          result = bk7258_gpio_result(
666	                     bk_gpio_set_interrupt_type(key->pin, type));
667	        }
668	    }
669	
670	  if (result == OK)
671	    {
672	      key->gpio.gp_pintype = pintype;
673	    }
674	
675	  nxmutex_unlock(&key->lock);
676	  return result;
677	}
