48	#if CONFIG_INTERRUPT_DEBUG_RECORDER
49	__attribute__((__used__)) static volatile interrupt_recorder_t  s_interrupt_flag[CONFIG_INTERRUPT_RECORDER_CNT] ;
50	__attribute__((__used__)) static volatile uint32_t s_int_cnt = 0;
51	
52	#define ARCH_ISR_HANDLER(irq)                                   \
53	{                                                               \
54		INT_INC_STATIS(irq);                                        \
55		IRQ_TRACE_BEGIN(irq);                                       \
56		int_group_isr_t isr_cb;                                     \
57		isr_cb = arch_interrupt_get_handler(irq);                   \
58	    s_interrupt_flag[s_int_cnt % CONFIG_INTERRUPT_RECORDER_CNT ].int_flag = irq;           \
59	    s_interrupt_flag[s_int_cnt % CONFIG_INTERRUPT_RECORDER_CNT].current_cnt = s_int_cnt;   \
60		if (isr_cb != NULL) {                                       \
61			(*(isr_cb))();                                          \
62		}                                                           \
63	    s_interrupt_flag[s_int_cnt % CONFIG_INTERRUPT_RECORDER_CNT].int_flag |= 0xf0000000;    \
64	    s_int_cnt ++;                                               \
65		IRQ_TRACE_END();                                            \
66	}
67	#else
68	#define ARCH_ISR_HANDLER(irq)                                   \
69	{                                                               \
70		INT_INC_STATIS(irq);                                        \
71		IRQ_TRACE_BEGIN(irq);                                       \
72		int_group_isr_t isr_cb;                                     \
73		isr_cb = arch_interrupt_get_handler(irq);                   \
74		if (isr_cb != NULL) {                                       \
75			(*(isr_cb))();                                          \
76		}                                                           \
77		IRQ_TRACE_END();                                            \
78	}
79	#endif
