146		NVIC_SetPriorityGrouping(PRI_GOURP_BITS_7_5);
147		for (uint32_t irq_type = 0; irq_type < INT_NUMBER_MAX; irq_type++) {
148			NVIC_SetPriority(irq_type, IRQ_DEFAULT_PRIORITY);
149			NVIC_EnableIRQ(irq_type);
