97	int bandgap_init(void)
98	{
99	#if (CONFIG_SOC_BK7236XX) && (CONFIG_OTP_V1)
100		uint8_t device_id[2]; //only check seqNUM
101		uint8_t new_bandgap;
102		uint8_t old_bandgap;
103		bk_err_t result;
104	
105		old_bandgap = (uint8_t)sys_drv_get_bgcalm();
106	
107		result = bk_otp_apb_read(OTP_VDDDIG_BANDGAP, &new_bandgap, sizeof(new_bandgap));
108		if ((result != BK_OK) || (new_bandgap == 0) || (new_bandgap > 0x3F)) {
109			goto default_bandgap;
110		}
111	
112		result = bk_otp_apb_read(OTP_DEVICE_ID, device_id, sizeof(device_id));
113		if ((result != BK_OK) || ((device_id[0] == 0x32) && (device_id[1] == 0x31))) {
114			goto default_bandgap;
115		}
116	
117		BK_LOGD(TAG, "bandgap_calm_in_otp=0x%x\r\n", new_bandgap);
118		if (old_bandgap != new_bandgap) {
119			sys_drv_set_bgcalm(new_bandgap);
120		}
121		return BK_OK;
122	
123	default_bandgap:
124		//tenglong20240717: increase 10mV as default
125		if (old_bandgap > 6) {
126			sys_drv_set_bgcalm(old_bandgap - 6);
127		}
128	#endif
129		return BK_OK;
130	}
